"""List action permissions and canonical edit navigation with origin context."""
http_support.client=admin_client
list_action_csrf,_=get_token('/settings')
_,_,list_action_project_url=call('/projects',{'_csrf':list_action_csrf,'name':'Interactions HTTP '+uuid.uuid4().hex[:6],'key':'UI'+uuid.uuid4().hex[:6].upper()})
list_action_pid=urllib.parse.parse_qs(urllib.parse.urlsplit(list_action_project_url).query)['project'][0]
_,_,list_action_ticket_url=call('/tickets',{'_csrf':list_action_csrf,'project_id':list_action_pid,'title':'Vérification des menus et modales','description':'Message initial pour les contrôles de saisie.','estimated_hours':'7.5','progress_percent':'60','due_date':'2026-11-20'})
list_action_tid=urllib.parse.urlsplit(list_action_ticket_url).path.rsplit('/',1)[-1]
list_action_source='/list?'+urllib.parse.urlencode({'project':list_action_pid,'q':'Vérification','sort':'due','direction':'asc'})
_,list_action_html,_=call(list_action_source)
check('data-quick-field="due_date"' not in list_action_html and 'data-quick-field="estimated_hours"' not in list_action_html,'list due date and estimate are read-only')
check('20/11/2026' in list_action_html and 'Estimé : 7 h 30 min' in list_action_html and 'title="Reste estimé : 3 h"' in list_action_html,'list keeps total estimate in the progress column and remaining effort in its tooltip')
list_action_link=re.search(r'href="([^"]+#ticket-edit-dialog)"',list_action_html)
check(list_action_link is not None and 'Ajouter un commentaire' in list_action_html and 'role="menu"' in list_action_html,'editor has menu actions and direct edit link')
list_action_href=__import__('html').unescape(list_action_link.group(1))
check(urllib.parse.parse_qs(urllib.parse.urlsplit(list_action_href).query)['return'][0]==list_action_source,'row action preserves list filters and ordering')
_,list_action_edit,_=call(list_action_href)
check('id="ticket-edit-dialog"' in list_action_edit and 'name="estimated_hours"' in list_action_edit and 'name="due_date"' in list_action_edit,'canonical ticket editor still exposes estimate and due date')
# An inline edit reports whether the ticket still matches the list filters, so the row can leave the table.
list_filters=__import__('html').unescape(re.search(r'data-match-filters="([^"]*)"',list_action_html).group(1))
check(json.loads(list_filters).get('q')=='Vérification' and 'data-refresh-view' in list_action_html,'list exposes its effective filters and a refresh button')
list_version=re.search(r'data-ticket-id="'+list_action_tid+r'" data-version="(\d+)"',list_action_html).group(1)
status,quick_body,_=call('/tickets/'+list_action_tid+'/quick',{'_csrf':list_action_csrf,'field':'priority','value':'high','version':list_version,'filters':list_filters,'filter_project':list_action_pid},True);quick_reply=json.loads(quick_body)
check(status==200 and quick_reply['matches_filters'] is True,'inline edit keeps a ticket that still matches the list filters')
status,quick_body,_=call('/tickets/'+list_action_tid+'/quick',{'_csrf':list_action_csrf,'field':'status','value':'paused','version':quick_reply['ticket']['version'],'filters':list_filters,'filter_project':list_action_pid},True);quick_reply=json.loads(quick_body)
check(status==200 and quick_reply['ticket']['status']=='paused' and quick_reply['matches_filters'] is False,'pausing from the list reports the ticket as leaving the default filters')
status,quick_body,_=call('/tickets/'+list_action_tid+'/quick',{'_csrf':list_action_csrf,'field':'status','value':'todo','version':quick_reply['ticket']['version'],'filters':'{"status":"inconnu"}','filter_project':list_action_pid},True);quick_reply=json.loads(quick_body)
check(status==200 and quick_reply['ticket']['status']=='todo' and quick_reply['matches_filters'] is None,'unreadable list filters never undo a saved inline edit')
_,list_action_html,_=call(list_action_source)
http_support.client=viewer_client
_,list_action_viewer,_=call(list_action_source)
check('#ticket-edit-dialog' not in list_action_viewer and '#ticket-comment-dialog' not in list_action_viewer and 'Copier le lien' in list_action_viewer,'read-only menu only exposes reading and copying actions')
_,list_action_viewer_ticket,_=call(list_action_href)
check('id="ticket-edit-dialog"' not in list_action_viewer_ticket,'edit fragment cannot expose editor to read-only account')
http_support.client=admin_client
print('UI inspection project '+list_action_pid+' ticket '+list_action_tid)
# Personal reports keep filters, column order and sorting in the account.
check('data-column="created"' in list_action_html and 'sort=created' in list_action_html,'creation column exposes chronological sorting')
_,sort_html,_=call('/list?project='+list_action_pid+'&sort=created&direction=desc')
check('aria-sort="descending"' in sort_html,'creation sort direction is accessible')
bulk_html=re.search(r'<form[^>]*id="bulk-form".*?</form>',list_action_html,re.S).group(0)
check('<select name="value"' in bulk_html and '<input name="value"' not in bulk_html and 'Personne assignée (identifiant)' not in bulk_html,'bulk edit uses value selector instead of raw technical input')
check(call('/bulk',{'_csrf':list_action_csrf,'ids[]':[list_action_tid],'field':'assignee_id','value':'none','_return':list_action_source})[2].endswith(list_action_source),'bulk unassignment accepts named choice and preserves list context')
report_data={'_csrf':list_action_csrf,'project_id':list_action_pid,'name':'Mes tickets importants','settings':json.dumps({'q':'Vérification'}),'report_options':'1','columns[]':['created','title','priority'],'column_order':json.dumps(['created','title','priority']),'sort':'created','direction':'desc','group':'priority','show_progress':'1'}
check(call('/views',{**report_data,'_csrf':''},True)[0]==403,'personal report save requires CSRF')
status,report_body,_=call('/views',report_data,True);report=json.loads(report_body)
check(status==200 and report['revision'] and report['id'],'personal report created through AJAX endpoint')
_,report_html,_=call(report['url'])
check('Mes tickets importants' in report_html and 'sort=created' in report_html,'saved report reloads filters sorting and its editable name')
headers=re.search(r'<thead>(.*?)</thead>',report_html,re.S).group(1)
check(headers.index('data-column="created"')<headers.index('data-column="title"')<headers.index('data-column="priority"'),'saved report renders columns in requested order')
check(re.search(r'<th[^>]*data-column="assignee"[^>]*hidden',headers) is not None,'saved report hides unselected columns on server render')
status,updated_body,_=call('/views',{**report_data,'view_id':report['id'],'revision':report['revision'],'name':'Mon suivi personnel'},True);updated=json.loads(updated_body)
check(status==200 and updated['id']==report['id'],'owner can rename and update same report without duplicates')
check(call('/views',{**report_data,'view_id':report['id'],'revision':report['revision']},True)[0]==422,'stale report update refused')
check(call('/views',{**report_data,'columns[]':['title','unknown']},True)[0]==422,'invalid report columns refused')
check(call('/views',{'_csrf':list_action_csrf,'project_id':list_action_pid,'name':'Invalide','settings':'{'},True)[0]==422,'malformed report JSON rejected as a validation error')
status,copy_body,_=call('/views',{**report_data,'view_id':report['id'],'mode':'copy','name':'Copie personnelle'},True);copy_report=json.loads(copy_body)
check(status==200 and copy_report['id']!=report['id'],'copy creates a separate personal report')
http_support.client=viewer_client;report_viewer_csrf,_=get_token('/list?project='+list_action_pid)
_,viewer_report_html,_=call(report['url'])
check('Mon suivi personnel' not in viewer_report_html and 'Mes tickets importants' not in viewer_report_html,'another user cannot load or list owner personal reports')
check(call('/views',{**report_data,'_csrf':report_viewer_csrf,'view_id':report['id'],'revision':updated['revision']},True)[0]==422,'another user cannot modify report by identifier')
check(call('/views/'+str(report['id'])+'/delete',{'_csrf':report_viewer_csrf},True)[0]==422,'another user cannot delete report by identifier')
http_support.client=admin_client
check(call('/views/'+str(copy_report['id'])+'/delete',{'_csrf':list_action_csrf},True)[0]==200,'owner deletes copied report by AJAX without touching tickets')
print('Personal report UI project '+list_action_pid+' report '+str(report['id']))
